package dev.veltraph.client.builder;
import dev.veltraph.client.config.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class Source95AcquisitionAuthorityTest {
 private Source95AcquisitionBinding binding(){return new Source95AcquisitionBinding(BuilderCropType.WHEAT,"Private Seeds","@vanilla",Set.of("Bazaar","Private Seeds"),Map.of("instant","Private Instant","stack","Private Stack"),500,100,30000);}
 private Source95AcquisitionAuthority.Scope scope(){return new Source95AcquisitionAuthority.Scope(new Object(),new Object(),new Object(),new Object(),new Object(),new Object(),2,3);}
 @Test void two64LegsUnderOneIntentAreProgressThen128NewAcquisition(){var a=new Source95AcquisitionAuthority();var s=scope();var intent=a.intent();assertTrue(a.issueLeg(binding(),s,64,192,1000,10,0));assertFalse(a.acknowledgeLeg(s,1000,64,192,true,11,true,true,1));assertTrue(a.acknowledgeLeg(s,1064,64,192,true,11,true,true,2));assertEquals(Source95AcquisitionAuthority.State.PROGRESS,a.state());assertEquals(64,a.remaining());var first=a.legReceiptId();assertTrue(a.issueLeg(binding(),s,64,192,1064,11,3));assertTrue(a.acknowledgeLeg(s,1128,64,192,true,12,true,true,4));assertEquals(intent,a.intent());assertNotEquals(first,a.legReceiptId());assertEquals(128,a.acquired());assertEquals(384,a.spent());assertEquals(Source95AcquisitionAuthority.State.CONFIRMED,a.state());}
 @Test void partial64CancelAndLateSecondReceiptNeverReplayOrComplete(){var a=new Source95AcquisitionAuthority();var s=scope();a.issueLeg(binding(),s,64,192,127,10,0);a.acknowledgeLeg(s,191,64,192,true,11,true,true,1);a.cancel();assertEquals(64,a.acquired());assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,a.state());assertFalse(a.issueLeg(binding(),s,64,192,191,11,2));assertFalse(a.acknowledgeLeg(s,255,64,192,true,12,true,true,3));}
 @Test void aggregateCapDoesNotResetPerLegAndReducedCapStopsAfterPartial(){var a=new Source95AcquisitionAuthority();var s=scope();a.issueLeg(binding(),s,64,300,0,10,0);a.acknowledgeLeg(s,64,64,300,true,11,true,true,1);assertFalse(a.issueLeg(binding(),s,64,201,64,11,2));var b=new Source95AcquisitionAuthority();b.issueLeg(binding(),s,64,192,0,10,0);b.acknowledgeLeg(s,64,64,192,true,11,true,true,1);b.reduceCap(100);assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,b.state());assertEquals(192,b.spent());}
 @Test void eachLegRequiresCurrentDeltaExactProductPostFloorCellsAndProtectedInventory(){var a=new Source95AcquisitionAuthority();var s=scope();a.issueLeg(binding(),s,64,192,127,10,0);assertFalse(a.acknowledgeLeg(s,191,64,192,true,11,false,true,1));assertFalse(a.acknowledgeLeg(s,191,64,192,true,10,true,true,2));assertFalse(a.acknowledgeLeg(s,190,64,192,true,11,true,true,3));assertFalse(a.acknowledgeLeg(s,191,64,192,false,11,true,true,4));assertFalse(a.acknowledgeLeg(s,191,64,192,true,11,true,false,5));assertFalse(a.acknowledgeLeg(s,191,63,192,true,11,true,true,6));assertTrue(a.acknowledgeLeg(s,191,64,192,true,11,true,true,7));}
 @Test void sameOwnerMenuScreenAndPWCRequiredAndIssuedLegCannotBeRepeated(){var a=new Source95AcquisitionAuthority();var s=scope();a.issueLeg(binding(),s,64,192,0,10,0);assertFalse(a.issueLeg(binding(),s,64,192,0,10,1));var foreign=new Source95AcquisitionAuthority.Scope(s.player(),s.world(),s.connection(),s.owner(),s.menu(),new Object(),s.menuId(),4);assertFalse(a.acknowledgeLeg(foreign,64,64,192,true,11,true,true,2));a.timedOut(30000);assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,a.state());}
}
